let ui;
const td={status:'COMPLETED',stage:4,segment:0,version:1,permission:'EDITOR',tab:'report',input:'',history:true,shared:false};
const stages=['获取作品','转写与时间定位','作者近期比较','内容分析','报告完成'];
const segments=[{time:'00:00–00:08',label:'钩子',text:'一个空间最重要的，不是放进去多少东西，而是留下什么。',reason:'用对比提出核心问题，建立空间与留白的主线。'},{time:'00:08–00:24',label:'论点',text:'我们让光线成为空间的一部分，让人在这里慢下来。',reason:'解释留白与体验之间的关系，服务主线。'},{time:'00:24–00:42',label:'案例',text:'从入口到窗边，每一个转角，都有一段可以停留的光。',reason:'用具体路径承接抽象主张，提供可理解的例子。'},{time:'00:42–00:58',label:'收束',text:'好的设计，是把生活的位置留给你。',reason:'回扣留白与生活，完成观点收束。'}];
const action=(text,key,primary=false,disabled=false)=>`<button class="btn ${primary?'primary':''}" data-td="${key}" ${disabled?'disabled':''}>${text}</button>`;
export function renderTeardown(h){ui=h;return `<div class="page teardown-page"><div class="breadcrumb"><a href="#research">研究</a> / 视频拆解</div><div class="page-heading"><div><div class="eyebrow">VIDEO TEARDOWN / EVIDENCE FIRST</div><h1>看懂一条视频，<br>留下可复用的判断。</h1><p>抖音链接 → 原文与时间轴 → 分析报告 → 项目创作</p></div><label class="td-role">查看权限<select id="td-role" aria-label="演示权限"><option value="EDITOR" ${td.permission==='EDITOR'?'selected':''}>可编辑 · 演示</option><option value="VIEWER" ${td.permission==='VIEWER'?'selected':''}>只读 · 演示</option></select></label></div><div class="td-input-bar"><label>${h.icon('clip')}<input id="td-input" aria-label="抖音链接或分享文字" placeholder="粘贴抖音视频链接或分享文字…" value="${h.esc(td.input)}"></label>${action('开始拆解','start',true,td.permission==='VIEWER')}<span class="badge">固定演示 · 不发起采集</span></div><div class="td-stepper">${stages.map((s,i)=>`<div class="${i<=td.stage?'done':''}"><i>${i<td.stage?'✓':i+1}</i><span>${s}</span></div>`).join('')}</div><div class="td-workspace"><aside class="td-history"><div class="panel-label">拆解历史</div>${td.history?`<button class="td-history-item selected" data-td="history"><img src="assets/architecture.svg" alt="空间叙事示例封面"><strong>留白之间 · 空间叙事</strong><small>v${td.version} · ${statusName()}</small></button>`:'<p class="backend-note">当前演示历史已移除</p>'}<a class="tree-row" href="#content">查看原始资料 ↗</a>${action('管理当前历史','manage-history',false,td.permission==='VIEWER')}<div class="td-limit"><span class="red-dot"></span><p>基于转写与公开记录分析。画面、配乐和观看留存不属于当前分析证据。</p></div></aside><section class="td-evidence"><div class="panel-top"><strong>原视频与依据</strong><span class="badge">示例资料</span></div><div class="td-video-poster"><img src="assets/architecture.svg" alt="视频预览位置示意，未加载真实视频"><span>视频预览位置 · 固定封面</span><button class="btn" data-td="media">核对原视频</button></div><div class="td-selected"><small>当前定位</small><strong id="td-time">${segments[td.segment].time}</strong><p id="td-quote">${segments[td.segment].text}</p></div><div class="td-evidence-heading">逐段原文 <span>58 秒 / 示例转写</span></div>${segments.map((s,i)=>`<button class="td-transcript ${td.segment===i?'selected':''}" data-td-segment="${i}"><small>${s.time}</small><p>${s.text}</p></button>`).join('')}</section><section class="td-report"><div class="panel-top"><strong>分析报告 <span class="badge">v${td.version}</span></strong><div>${action('导出 Markdown','export',false,td.status!=='COMPLETED')}${action('加入项目','share',true,td.status!=='COMPLETED'||td.permission==='VIEWER')}</div></div><div class="td-tabs">${[['report','内容报告'],['comparison','作者比较'],['states','任务状态']].map(([id,label])=>`<button data-td-tab="${id}" aria-pressed="${td.tab===id}">${label}</button>`).join('')}</div><div class="td-report-body">${td.status==='COMPLETED'?report():taskState()}</div></section></div><div class="backend-context"><strong>链路状态演示</strong>${['complete','progress','fail'].map((x,i)=>action(['查看完成报告','查看执行中','查看失败重试'][i],x))}<a class="btn" href="#capabilities">检查功能与接口对应 →</a></div>${h.footer()}</div>`}
function statusName(){return {COMPLETED:'已完成',RUNNING:'执行中',FAILED:'失败',CANCELLED:'已停止'}[td.status]}
function report(){if(td.tab==='states')return taskState();if(td.tab==='comparison')return `<span class="eyebrow">PUBLIC SNAPSHOT / COMPUTED</span><h2>放回作者自己的近期作品中比较。</h2><div class="td-metrics"><div><small>有效样本</small><strong>24</strong></div><div><small>点赞中位数</small><strong>1,280</strong></div><div><small>当前作品 / 中位数</small><strong>2.00×</strong></div></div><div class="td-report-note">收藏 / 赞 25.0% · 分享 / 赞 7.0% · 评论 / 赞 4.4%。示例以点赞为分母，不是播放互动率；点赞为零或指标缺失时不计算。</div><p>示例作品点赞 2,560；最近 60 天，最多 60 条。排除本作品、重复、已知置顶与缺失数据。</p><div class="td-report-note">有效样本不足 20 条或中位数小于 50 时不计算倍数。公开累计点赞未经曝光量和发布时长校正，不用于认定爆款或因果。</div>${action('查看样本与缺失情况','samples')}`;return `<span class="eyebrow">TRANSCRIPT → STRUCTURE → FINDINGS</span><h2>留白，让空间回到人的体验。</h2><p>作者通过“少放一些东西”的反问，引出光线、停留与生活位置的关系。</p><div class="td-metrics"><div><small>语义段落</small><strong>4</strong></div><div><small>转写时长</small><strong>00:58</strong></div><div><small>数据来源</small><strong>示例</strong></div></div><h3>分段时间轴</h3><div class="td-timeline">${segments.map((s,i)=>`<button data-td-segment="${i}" class="${i===td.segment?'selected':''}"><span>${s.label}</span><small>${s.time}</small></button>`).join('')}</div><div class="td-analysis-selected"><span class="badge">服务主线 · AI 判断</span><h3>${segments[td.segment].label} / ${segments[td.segment].time}</h3><p>${segments[td.segment].reason}</p>${action('定位对应原文','locate')}</div><div class="td-finding"><h3>做对了什么</h3><p>抽象观点之后紧接具体空间路径，读者能把主张与场景联系起来。</p>${action('查看原文依据 00:24','evidence')}</div><div class="td-finding"><h3>主线风险</h3><p>本示例没有足够原文证据判定明确跑题。真实报告按 distractions 字段展示判断和对应段落，不自动补出风险。</p></div><div class="td-finding"><h3>为什么可能传播</h3><span class="badge">传播机制 · AI 假设</span><p>“少即是多”的对比可能引起对生活空间的讨论。它是有转写依据的解释，不代表已证实传播因果。</p></div><div class="td-finding"><h3>热点与阶段关联</h3><span class="badge">尚未核实</span><p>本示例未附真实榜单快照；关联判断需展示采集时间、榜单范围与来源。</p></div><div class="td-report-note">完整链路为固定交互演示。报告保存由实际任务记录承载，导出文件包含示例标记；不生成或播放真实视频。</div>${action('更新分析','refresh',false,td.permission==='VIEWER')}`}
function taskState(){return `<span class="eyebrow">TASK / ${td.status}</span><h2>${statusName()}</h2><p>${td.status==='FAILED'?'示例错误：转写未包含可核验时间戳，无法建立分段时间轴。':td.status==='CANCELLED'?'演示任务已停止；已有资料保留。':'当前阶段：'+stages[td.stage]+'。后台真实阶段由任务接口返回。'}</p><div class="td-report-note">失败时保留来源与最后完成阶段。未配置模型、采集服务或 Worker 未就绪时，应提供明确提示与设置入口。</div><div class="backend-actions">${action('重试当前任务','retry',true,td.permission==='VIEWER'||!['FAILED','CANCELLED'].includes(td.status))}${action('停止任务','cancel',false,td.permission==='VIEWER'||td.status!=='RUNNING')}<a class="btn" href="#settings">检查服务配置</a></div>`}
function repaint(){document.querySelector('#main').innerHTML=renderTeardown(ui)}
export function teardownReference(){return '留白之间 · 视频拆解报告'}
document.addEventListener('input',e=>{if(e.target.id==='td-input')td.input=e.target.value});
document.addEventListener('change',e=>{if(e.target.id==='td-role'){td.permission=e.target.value;repaint()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-td],[data-td-segment],[data-td-tab]');if(!b||!ui)return;if(b.dataset.tdSegment!==undefined){td.segment=Number(b.dataset.tdSegment);repaint();return}if(b.dataset.tdTab){td.tab=b.dataset.tdTab;repaint();return}
switch(b.dataset.td){case 'history':ui.toast('当前示例拆解已选中');break;case 'start':if(!td.input.trim())return ui.toast('请先输入抖音链接或分享文字');if(!/https?:\/\/[^\s]*douyin\.com\//i.test(td.input))return ui.toast('当前专用接口支持抖音链接；其他来源保留资料入口');td.status='RUNNING';td.stage=0;td.history=true;repaint();ui.toast('已开始本地流程演示，未发起采集');break;
case 'progress':td.status='RUNNING';td.stage=1;repaint();break;case 'fail':td.status='FAILED';td.stage=1;repaint();break;case 'complete':td.status='COMPLETED';td.stage=4;td.tab='report';repaint();break;case 'cancel':td.status='CANCELLED';repaint();break;case 'retry':td.status='RUNNING';td.stage=1;repaint();break;case 'refresh':td.version++;td.status='RUNNING';td.stage=3;repaint();break;
case 'locate':document.querySelector('.td-transcript.selected').scrollIntoView({block:'center',behavior:'smooth'});break;case 'evidence':td.segment=2;repaint();break;
case 'media':ui.modal('核对原视频','<p class="dialog-copy">正式链路使用资料资产 access 接口取得预览地址，再按真实转写时间 seek。当前无示例视频文件，因此只展示封面和原文定位。</p>','<button class="btn" data-action="close">关闭</button>');break;
case 'samples':ui.modal('比较口径与缺失值','<p class="dialog-copy">当前 24 条样本、1,280 中位数和 2 倍均为固定示例。真实比较必须使用同作者、最近 60 天的有效公开记录；缺失播放与置顶标识需明确提示。</p>','<button class="btn" data-action="close">关闭</button>');break;
case 'share':ui.modal('审阅报告后加入项目','<p class="dialog-copy">正文、来源和局限一并保留。现有接口支持加入已有项目或创建新项目，并校验报告版本。</p><label class="field">目标项目<select id="td-target"><option>向新而行 · 品牌企划</option><option>留白之间 · 空间叙事</option></select></label><details><summary>查看将加入的报告摘要</summary><p class="dialog-copy">主线：留白让空间回到人的体验。含 4 段转写依据、作者比较口径与解释边界。示例报告 v'+td.version+'。</p></details>','<button class="btn primary" data-td="confirm-share">加入并继续创作</button>');break;
case 'confirm-share':td.shared=true;document.dispatchEvent(new CustomEvent('teardown-handoff',{detail:{title:document.querySelector('#td-target').value,reference:teardownReference()}}));document.querySelector('#dialog').close();location.hash='studio';break;
case 'manage-history':ui.modal('移除当前演示历史','<p class="dialog-copy">对应专用历史删除接口。真实操作只移除个人拆解记录，不删除资料或已加入项目的成果。本次只修改浏览会话。</p>','<button class="btn" data-td="delete-history">确认移除演示历史</button>');break;case 'delete-history':td.history=false;document.querySelector('#dialog').close();repaint();break;
case 'export':{const body='# 视频拆解报告 · 固定演示\n\n主线：留白让空间回到人的体验。\n\n'+segments.map(s=>`## ${s.time} ${s.label}\n${s.text}\n判断：${s.reason}`).join('\n\n')+'\n\n本文件为原型示例。未分析画面、配乐、观看留存，不代表真实视频分析。';const url=URL.createObjectURL(new Blob([body],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='视频拆解-示例报告.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}
}});
